
/* --- BUNDLED: navigation.js --- */
window.CourseForgeNav=(function(){const STORAGE_KEY_URL='cf_last_course_url';const STORAGE_KEY_NAME='cf_last_course_name';return{storeContext:function(name,url,isSubcourse){if(!isSubcourse){const absoluteUrl=new URL(url,window.location.href).pathname;sessionStorage.setItem(STORAGE_KEY_URL,absoluteUrl);sessionStorage.setItem(STORAGE_KEY_NAME,name);}},getBackLink:function(defaultUrl,defaultText,isSubcourse){const lastUrl=sessionStorage.getItem(STORAGE_KEY_URL);const lastName=sessionStorage.getItem(STORAGE_KEY_NAME);if(isSubcourse&&lastUrl){return{url:lastUrl,text:'Voltar para '+lastName};}
return{url:defaultUrl,text:defaultText};},applyDynamicBackLink:function(selector,defaultUrl,defaultText,isSubcourse){const link=document.querySelector(selector);if(!link)return;const dynamic=this.getBackLink(defaultUrl,defaultText,isSubcourse);link.href=dynamic.url;const icon=link.querySelector('[data-lucide]');if(icon){link.innerHTML='';link.appendChild(icon);link.appendChild(document.createTextNode(' '+dynamic.text));}else{link.textContent=dynamic.text;}},applyDynamicBreadcrumbs:function(selector,isSubcourse){const container=document.querySelector(selector);if(!container||!isSubcourse)return;const lastUrl=sessionStorage.getItem(STORAGE_KEY_URL);const lastName=sessionStorage.getItem(STORAGE_KEY_NAME);if(lastUrl&&lastName){const firstCrumb=container.querySelector('.breadcrumb-link, .breadcrumb-part');if(firstCrumb&&firstCrumb.textContent.trim().toLowerCase()===lastName.trim().toLowerCase()){return;}
const crumb=document.createElement('a');crumb.href=lastUrl;crumb.className='breadcrumb-link';crumb.textContent=lastName;const separator=document.createElement('span');separator.className='breadcrumb-separator';separator.innerHTML='<i data-lucide="chevron-right" class="breadcrumb-icon"></i>';container.insertBefore(separator,container.firstChild);container.insertBefore(crumb,container.firstChild);if(typeof lucide!=='undefined'){lucide.createIcons();}}},toggleSidebar:function(){const body=document.body;const isHidden=body.classList.toggle('sidebar-hidden');localStorage.setItem('cf_sidebar_hidden',isHidden);const icon=document.getElementById('sidebar-toggle-icon');if(icon){icon.setAttribute('data-lucide',isHidden?'chevron-right':'chevron-left');if(typeof CourseForgeUI!=='undefined'){CourseForgeUI.initIcons();}}},initSidebar:function(){const isHidden=localStorage.getItem('cf_sidebar_hidden')==='true';if(isHidden){document.body.classList.add('sidebar-hidden');}},initScrollSpy:function(){const tocLinks=document.querySelectorAll('.toc-item a');if(tocLinks.length===0)return;const sections=[];let isScrollingFromClick=false;let scrollEndTimer=null;tocLinks.forEach(link=>{const id=link.getAttribute('href').substring(1);const element=document.getElementById(id);if(element){sections.push({id,link:link.parentElement,element});}});function updateActive(){if(isScrollingFromClick)return;const scrollPos=window.scrollY;const windowHeight=window.innerHeight;const bodyHeight=document.body.offsetHeight;let activeSection=null;if(scrollPos<100&&sections.length>0){activeSection=sections[0];}
else if(scrollPos+windowHeight>=bodyHeight-50&&sections.length>0){activeSection=sections[sections.length-1];}
else{const offset=120;for(let i=0;i<sections.length;i++){const section=sections[i];if(section.element.offsetTop-offset<=scrollPos){activeSection=section;}else{break;}}}
if(activeSection){sections.forEach(s=>s.link.classList.remove('active'));activeSection.link.classList.add('active');const sidebarToc=document.querySelector('.toc-list');if(sidebarToc){const linkRect=activeSection.link.getBoundingClientRect();const tocRect=sidebarToc.getBoundingClientRect();if(linkRect.top<tocRect.top||linkRect.bottom>tocRect.bottom){activeSection.link.scrollIntoView({behavior:'auto',block:'nearest'});}}}}
window.addEventListener('scroll',updateActive,{passive:true});tocLinks.forEach(link=>{link.addEventListener('click',(e)=>{isScrollingFromClick=true;if(scrollEndTimer)clearTimeout(scrollEndTimer);sections.forEach(s=>s.link.classList.remove('active'));link.parentElement.classList.add('active');scrollEndTimer=setTimeout(()=>{isScrollingFromClick=false;},1000);});});updateActive();}};})();
;

/* --- BUNDLED: ui.js --- */
window.CourseForgeUI=(function(){return{initIcons:function(){if(typeof lucide!=='undefined'){lucide.createIcons();}},initCopyButtons:function(){const preBlocks=document.querySelectorAll('pre[class*="language-"]');preBlocks.forEach(pre=>{if(pre.querySelector('.copy-button'))return;const button=document.createElement('button');button.className='copy-button';button.setAttribute('aria-label','Copiar código');button.innerHTML='<i data-lucide="copy"></i>';pre.appendChild(button);button.addEventListener('click',async()=>{const code=pre.querySelector('code');if(!code)return;const text=code.innerText;let success=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);success=true;}else{const textArea=document.createElement('textarea');textArea.value=text;textArea.style.position='fixed';textArea.style.left='-9999px';textArea.style.top='0';document.body.appendChild(textArea);textArea.focus();textArea.select();try{success=document.execCommand('copy');}catch(err){console.error('Fallback copy failed',err);}
document.body.removeChild(textArea);}
if(success){button.innerHTML='<i data-lucide="check" style="color: #1dac52ff;"></i>';this.initIcons();setTimeout(()=>{button.innerHTML='<i data-lucide="copy"></i>';this.initIcons();},2000);}}catch(err){console.error('Failed to copy: ',err);}});});this.initIcons();},initExamples:function(){var pageKey=location.pathname;var blockSelectors=['.example','.exam','.assignment','.question','.questions','.block-slide','.block-presentation'];var examples=document.querySelectorAll(blockSelectors.join(','));examples.forEach(function(example,idx){var blockClass="";blockSelectors.forEach(function(cls){if(example.classList.contains(cls.substring(1))){blockClass=cls.substring(1);}});var titleSelector='.'+blockClass+'-title';var contentClass=blockClass+'-content';var collapsedClass=blockClass+'-collapsed';var title=example.querySelector(titleSelector);if(!title||title.dataset.initialized)return;title.dataset.initialized='true';var chevron=document.createElement('i');chevron.setAttribute('data-lucide','chevron-down');chevron.className='example-chevron';title.appendChild(chevron);var content=example.querySelector('.'+contentClass);if(!content){content=document.createElement('div');content.className=contentClass;while(title.nextSibling){content.appendChild(title.nextSibling);}
example.appendChild(content);}
var storageKey='cf-ex:'+pageKey+':'+(title.textContent.trim()||idx);var savedState=localStorage.getItem(storageKey);var startCollapsed=savedState===null||savedState==='collapsed';if(startCollapsed){content.style.height='0';example.classList.add(collapsedClass);}else{content.style.height='auto';example.classList.remove(collapsedClass);}
var pendingTimer=null;title.addEventListener('click',function(){if(pendingTimer!==null){clearTimeout(pendingTimer);pendingTimer=null;}
var isCollapsed=example.classList.contains(collapsedClass);if(isCollapsed){content.style.transition='none';content.style.height='0';content.offsetHeight;content.style.transition='';var targetHeight=content.scrollHeight;content.style.height=targetHeight+'px';example.classList.remove(collapsedClass);pendingTimer=setTimeout(function(){content.style.height='auto';pendingTimer=null;},350);localStorage.setItem(storageKey,'expanded');}else{content.style.transition='none';content.style.height=content.scrollHeight+'px';content.offsetHeight;content.style.transition='';content.style.height='0';example.classList.add(collapsedClass);pendingTimer=setTimeout(function(){pendingTimer=null;},350);localStorage.setItem(storageKey,'collapsed');}});});this.initIcons();},switchMermaidView:function(button,mode){const container=button.closest('.mermaid-outer-container');if(!container)return;const display=container.querySelector('.mermaid-display');const source=container.querySelector('.mermaid-source');const buttons=container.querySelectorAll('.switcher-btn');buttons.forEach(btn=>btn.classList.remove('active'));button.classList.add('active');if(mode==='code'){display.style.display='none';source.style.display='block';}else{source.style.display='none';display.style.display='block';}}};})();
;
